/* Lei seca da Revisão — redação oficial, sem texto autoral. Gerado por scripts/build-lei-revisao.mjs. */
(function(g){g.BC_LEI_REVISAO=g.BC_LEI_REVISAO||{};g.BC_LEI_REVISAO["adm"]=g.BC_LEI_REVISAO["adm"]||{};g.BC_LEI_REVISAO["adm"][6]=[{"key":"cf:37","law":"cf","ref":"37","label":"Constituição Federal · CF/88 · Art. 37","paragraphs":["Art. 37. A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte: (“Caput” do artigo com redação dada pela Emenda Constitucional nº 19, de 1998)","I - os cargos, empregos e funções públicas são acessíveis aos brasileiros que preencham os requisitos estabelecidos em lei, assim como aos estrangeiros, na forma da lei; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","II - a investidura em cargo ou emprego público depende de aprovação prévia em concurso público de provas ou de provas e títulos, de acordo com a natureza e a complexidade do cargo ou emprego, na forma prevista em lei, ressalvadas as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","III - o prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por igual período;","IV - durante o prazo improrrogável previsto no edital de convocação, aquele aprovado em concurso público de provas ou de provas e títulos será convocado com prioridade sobre novos concursados para assumir cargo ou emprego, na carreira;","V - as funções de confiança, exercidas exclusivamente por servidores ocupantes de cargo efetivo, e os cargos em comissão, a serem preenchidos por servidores de carreira nos casos, condições e percentuais mínimos previstos em lei, destinam-se apenas às atribuições de direção, chefia e assessoramento; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VI - é garantido ao servidor público civil o direito à livre associação sindical;","VII - o direito de greve será exercido nos termos e nos limites definidos em lei específica; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","VIII - a lei reservará percentual dos cargos e empregos públicos para as pessoas portadoras de deficiência e definirá os critérios de sua admissão;","IX - a lei estabelecerá os casos de contratação por tempo determinado para atender a necessidade temporária de excepcional interesse público;","X - a remuneração dos servidores públicos e o subsídio de que trata o § 4º do art. 39 somente poderão ser fixados ou alterados por lei específica, observada a iniciativa privativa em cada caso, assegurada revisão geral anual, sempre na mesma data e sem distinção de índices; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XI - a remuneração e o subsídio dos ocupantes de cargos, funções e empregos públicos da administração direta, autárquica e fundacional, dos membros de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, dos detentores de mandato eletivo e dos demais agentes políticos e os proventos, pensões ou outra espécie remuneratória, percebidos cumulativamente ou não, incluídas as vantagens pessoais ou de qualquer outra natureza, não poderão exceder o subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, aplicando-se como limite, nos Municípios, o subsídio do Prefeito, e nos Estados e no Distrito Federal, o subsídio mensal do Governador no âmbito do Poder Executivo, o subsídio dos Deputados Estaduais e Distritais no âmbito do Poder Legislativo e o subsídio dos Desembargadores do Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal, em espécie, dos Ministros do Supremo Tribunal Federal, no âmbito do Poder Judiciário, aplicável este limite aos membros do Ministério Público, aos Procuradores e aos Defensores Públicos; (Inciso com redação dada pela Emenda Constitucional nº 41, de 2003)","XII - os vencimentos dos cargos do Poder Legislativo e do Poder Judiciário não poderão ser superiores aos pagos pelo Poder Executivo;","XIII - é vedada a vinculação ou equiparação de quaisquer espécies remuneratórias para o efeito de remuneração de pessoal do serviço público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XIV - os acréscimos pecuniários percebidos por servidor público não serão computados nem acumulados para fins de concessão de acréscimos ulteriores; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XV - o subsídio e os vencimentos dos ocupantes de cargos e empregos públicos são irredutíveis, ressalvado o disposto nos incisos XI e XIV deste artigo e nos arts. 39, § 4º, 150, II, 153, III, e 153, § 2º, I; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVI - é vedada a acumulação remunerada de cargos públicos, exceto, quando houver compatibilidade de horários, observado em qualquer caso o disposto no inciso XI: (“Caput” do inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","a) a de dois cargos de professor;","b) a de um cargo de professor com outro de qualquer natureza; (Alínea com redação dada pela Emenda Constitucional nº 138, de 2025)","c) a de dois cargos ou empregos privativos de profissionais de saúde, com profissões regulamentadas; (Alínea com redação dada pela Emenda Constitucional nº 34, de 2001)","XVII - a proibição de acumular estende-se a empregos e funções e abrange autarquias, fundações, empresas públicas, sociedades de economia mista, suas subsidiárias, e sociedades controladas, direta ou indiretamente, pelo poder público; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XVIII - a administração fazendária e seus servidores fiscais terão, dentro de suas áreas de competência e jurisdição, precedência sobre os demais setores administrativos, na forma da lei;","XIX - somente por lei específica poderá ser criada autarquia e autorizada a instituição de empresa pública, de sociedade de economia mista e de fundação, cabendo à lei complementar, neste último caso, definir as áreas de sua atuação; (Inciso com redação dada pela Emenda Constitucional nº 19, de 1998)","XX - depende de autorização legislativa, em cada caso, a criação de subsidiárias das entidades mencionadas no inciso anterior, assim como a participação de qualquer delas em empresa privada;","XXI - ressalvados os casos especificados na legislação, as obras, serviços, compras e alienações serão contratados mediante processo de licitação pública que assegure igualdade de condições a todos os concorrentes, com cláusulas que estabeleçam obrigações de pagamento, mantidas as condições efetivas da proposta, nos termos da lei, o qual somente permitirá as exigências de qualificação técnica e econômica indispensáveis à garantia do cumprimento das obrigações.","XXII - as administrações tributárias da União, dos Estados, do Distrito Federal e dos Municípios, atividades essenciais ao funcionamento do Estado, exercidas por servidores de carreiras específicas, terão recursos prioritários para a realização de suas atividades e atuarão de forma integrada, inclusive com o compartilhamento de cadastros e de informações fiscais, na forma da lei ou convênio. (Inciso acrescido pela Emenda Constitucional nº 42, de 2003)","§ 1º A publicidade dos atos, programas, obras, serviços e campanhas dos órgãos públicos deverá ter caráter educativo, informativo ou de orientação social, dela não podendo constar nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores públicos.","§ 2º A não-observância do disposto nos incisos II e III implicará a nulidade do ato e a punição da autoridade responsável, nos termos da lei.","§ 3º A lei disciplinará as formas de participação do usuário na administração pública direta e indireta, regulando especialmente:","I - as reclamações relativas à prestação dos serviços públicos em geral, asseguradas a manutenção de serviços de atendimento ao usuário e a avaliação periódica, externa e interna, da qualidade dos serviços;","II - o acesso dos usuários a registros administrativos e a informações sobre atos de governo, observado o disposto no art. 5º, X e XXXIII;","III - a disciplina da representação contra o exercício negligente ou abusivo de cargo, emprego ou função na administração pública. (Parágrafo com redação dada pela Emenda Constitucional nº 19, de 1998)","§ 4º Os atos de improbidade administrativa importarão a suspensão dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.","§ 5º A lei estabelecerá os prazos de prescrição para ilícitos praticados por qualquer agente, servidor ou não, que causem prejuízos ao erário, ressalvadas as respectivas ações de ressarcimento.","§ 6º As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.","§ 7º A lei disporá sobre os requisitos e as restrições ao ocupante de cargo ou emprego da administração direta e indireta que possibilite o acesso a informações privilegiadas. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 8º A autonomia gerencial, orçamentária e financeira dos órgãos e entidades da administração direta e indireta poderá ser ampliada mediante contrato, a ser firmado entre seus administradores e o poder público, que tenha por objeto a fixação de metas de desempenho para o órgão ou entidade, cabendo à lei dispor sobre:","I - o prazo de duração do contrato;","II - os controles e critérios de avaliação de desempenho, direitos, obrigações e responsabilidade dos dirigentes;","III - a remuneração do pessoal. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 9º O disposto no inciso XI aplica-se às empresas públicas e às sociedades de economia mista, e suas subsidiárias, que receberem recursos da União, dos Estados, do Distrito Federal ou dos Municípios para pagamento de despesas de pessoal ou de custeio em geral. (Parágrafo acrescido pela Emenda Constitucional nº 19, de 1998)","§ 10. É vedada a percepção simultânea de proventos de aposentadoria decorrentes do art. 40 ou dos arts. 42 e 142 com a remuneração de cargo, emprego ou função pública, ressalvados os cargos acumuláveis na forma desta Constituição, os cargos eletivos e os cargos em comissão declarados em lei de livre nomeação e exoneração. (Parágrafo acrescido pela Emenda Constitucional nº 20, de 1998)","§ 11. Não serão computadas, para efeito dos limites remuneratórios de que trata o inciso XI do caput deste artigo, as parcelas de caráter indenizatório expressamente previstas em lei ordinária, aprovada pelo Congresso Nacional, de caráter nacional, aplicada a todos os Poderes e órgãos constitucionalmente autônomos. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005, e com redação dada pela Emenda Constitucional nº 135, de 2024)","§ 12. Para os fins do disposto no inciso XI do caput deste artigo, fica facultado aos Estados e ao Distrito Federal fixar, em seu âmbito, mediante emenda às respectivas Constituições e Lei Orgânica, como limite único, o subsídio mensal dos Desembargadores do respectivo Tribunal de Justiça, limitado a noventa inteiros e vinte e cinco centésimos por cento do subsídio mensal dos Ministros do Supremo Tribunal Federal, não se aplicando o disposto neste parágrafo aos subsídios dos Deputados Estaduais e Distritais e dos Vereadores. (Parágrafo acrescido pela Emenda Constitucional nº 47, de 2005)","§ 13. O servidor público titular de cargo efetivo poderá ser readaptado para exercício de cargo cujas atribuições e responsabilidades sejam compatíveis com a limitação que tenha sofrido em sua capacidade física ou mental, enquanto permanecer nesta condição, desde que possua a habilitação e o nível de escolaridade exigidos para o cargo de destino, mantida a remuneração do cargo de origem. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 14. A aposentadoria concedida com a utilização de tempo de contribuição decorrente de cargo, emprego ou função pública, inclusive do Regime Geral de Previdência Social, acarretará o rompimento do vínculo que gerou o referido tempo de contribuição. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 15. É vedada a complementação de aposentadorias de servidores públicos e de pensões por morte a seus dependentes que não seja decorrente do disposto nos §§ 14 a 16 do art. 40 ou que não seja prevista em lei que extinga regime próprio de previdência social. (Parágrafo acrescido pela Emenda Constitucional nº 103, de 2019)","§ 16. Os órgãos e entidades da administração pública, individual ou conjuntamente, devem realizar avaliação das políticas públicas, inclusive com divulgação do objeto a ser avaliado e dos resultados alcançados, na forma da lei. (Parágrafo acrescido pela Emenda Constitucional nº 109, de 2021)","§ 17. (Vide Emenda Constitucional nº 132, de 2023)","§ 18. (Vide Emenda Constitucional nº 132, de 2023)"],"url":""},{"key":"l9784:1","law":"l9784","ref":"1","label":"Lei do Processo Administrativo Federal · Art. 1","paragraphs":["Art. 1º Esta Lei estabelece normas básicas sobre o processo administrativo no âmbito da Administração Federal direta e indireta, visando, em especial, à proteção dos direitos dos administrados e ao melhor cumprimento dos fins da Administração.","§ 1º Os preceitos desta Lei também se aplicam aos órgãos dos Poderes Legislativo e Judiciário da União, quando no desempenho de função administrativa.","§ 2º Para os fins desta Lei, consideram-se:","I - órgão - a unidade de atuação integrante da estrutura da Administração direta e da estrutura da Administração indireta;","II - entidade - a unidade de atuação dotada de personalidade jurídica;","III - autoridade - o servidor ou agente público dotado de poder de decisão."],"url":""},{"key":"l9784:2","law":"l9784","ref":"2","label":"Lei do Processo Administrativo Federal · Art. 2","paragraphs":["Art. 2º A Administração Pública obedecerá, dentre outros, aos princípios da legalidade, finalidade, motivação, razoabilidade, proporcionalidade, moralidade, ampla defesa, contraditório, segurança jurídica, interesse público e eficiência.","Parágrafo único. Nos processos administrativos serão observados, entre outros, os critérios de:","I - atuação conforme a lei e o Direito;","II - atendimento a fins de interesse geral, vedada a renúncia total ou parcial de poderes ou competências, salvo autorização em lei;","III - objetividade no atendimento do interesse público, vedada a promoção pessoal de agentes ou autoridades;","IV - atuação segundo padrões éticos de probidade, decoro e boa-fé;","V - divulgação oficial dos atos administrativos, ressalvadas as hipóteses de sigilo previstas na Constituição;","VI - adequação entre meios e fins, vedada a imposição de obrigações, restrições e sanções em medida superior àquelas estritamente necessárias ao atendimento do interesse público;","VII - indicação dos pressupostos de fato e de direito que determinarem a decisão;","VIII - observância das formalidades essenciais à garantia dos direitos dos administrados;","IX - adoção de formas simples, suficientes para propiciar adequado grau de certeza, segurança e respeito aos direitos dos administrados;","X - garantia dos direitos à comunicação, à apresentação de alegações finais, à produção de provas e à interposição de recursos, nos processos de que possam resultar sanções e nas situações de litígio;","XI - proibição de cobrança de despesas processuais, ressalvadas as previstas em lei;","XII - impulsão, de ofício, do processo administrativo, sem prejuízo da atuação dos interessados;","XIII - interpretação da norma administrativa da forma que melhor garanta o atendimento do fim público a que se dirige, vedada aplicação retroativa de nova interpretação."],"url":""},{"key":"lindb:20","law":"lindb","ref":"20","label":"LINDB · LINDB · Art. 20","paragraphs":["Art. 20. Nas esferas administrativa, controladora e judicial, não se decidirá com base em valores jurídicos abstratos sem que sejam consideradas as consequências práticas da decisão.","Parágrafo único. A motivação demonstrará a necessidade e a adequação da medida imposta ou da invalidação de ato, contrato, ajuste, processo ou norma administrativa, inclusive em face das possíveis alternativas. (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"lindb:24","law":"lindb","ref":"24","label":"LINDB · LINDB · Art. 24","paragraphs":["Art. 24. A revisão, nas esferas administrativa, controladora ou judicial, quanto à validade de ato, contrato, ajuste, processo ou norma administrativa cuja produção já se houver completado levará em conta as orientações gerais da época, sendo vedado que, com base em mudança posterior de orientação geral, se declarem inválidas situações plenamente constituídas.","Parágrafo único. Consideram-se orientações gerais as interpretações e especificações contidas em atos públicos de caráter geral ou em jurisprudência judicial ou administrativa majoritária, e ainda as adotadas por prática administrativa reiterada e de amplo conhecimento público. (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"lindb:21","law":"lindb","ref":"21","label":"LINDB · LINDB · Art. 21","paragraphs":["Art. 21. A decisão que, nas esferas administrativa, controladora ou judicial, decretar a invalidação de ato, contrato, ajuste, processo ou norma administrativa deverá indicar de modo expresso suas consequências jurídicas e administrativas.","Parágrafo único. A decisão a que se refere o caput deste artigo deverá, quando for o caso, indicar as condições para que a regularização ocorra de modo proporcional e equânime e sem prejuízo aos interesses gerais, não se podendo impor aos sujeitos atingidos ônus ou perdas que, em função das peculiaridades do caso, sejam anormais ou excessivos. (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"lindb:22","law":"lindb","ref":"22","label":"LINDB · LINDB · Art. 22","paragraphs":["Art. 22. Na interpretação de normas sobre gestão pública, serão considerados os obstáculos e as dificuldades reais do gestor e as exigências das políticas públicas a seu cargo, sem prejuízo dos direitos dos administrados.","§ 1º Em decisão sobre regularidade de conduta ou validade de ato, contrato, ajuste, processo ou norma administrativa, serão consideradas as circunstâncias práticas que houverem imposto, limitado ou condicionado a ação do agente.","§ 2º Na aplicação de sanções, serão consideradas a natureza e a gravidade da infração cometida, os danos que dela provierem para a administração pública, as circunstâncias agravantes ou atenuantes e os antecedentes do agente.","§ 3º As sanções aplicadas ao agente serão levadas em conta na dosimetria das demais sanções de mesma natureza e relativas ao mesmo fato. (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"lindb:23","law":"lindb","ref":"23","label":"LINDB · LINDB · Art. 23","paragraphs":["Art. 23. A decisão administrativa, controladora ou judicial que estabelecer interpretação ou orientação nova sobre norma de conteúdo indeterminado, impondo novo dever ou novo condicionamento de direito, deverá prever regime de transição quando indispensável para que o novo dever ou condicionamento de direito seja cumprido de modo proporcional, equânime e eficiente e sem prejuízo aos interesses gerais.","Parágrafo único. (VETADO). (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)"],"url":""},{"key":"lindb:30","law":"lindb","ref":"30","label":"LINDB · LINDB · Art. 30","paragraphs":["Art. 30. As autoridades públicas devem atuar para aumentar a segurança jurídica na aplicação das normas, inclusive por meio de regulamentos, súmulas administrativas e respostas a consultas.","Parágrafo único. Os instrumentos previstos no caput deste artigo terão caráter vinculante em relação ao órgão ou entidade a que se destinam, até ulterior revisão. (Artigo acrescido pela Lei nº 13.655, de 25/4/2018)","Rio de Janeiro, 4 de setembro de 1942, 121º da Independência e 54º da República.","Alexandre Marcondes Filho","A. de Souza Costa","Eurico G. Dutra","Henrique A. Guilhem","Oswaldo Aranha","Apolonio Salles","Gustavo Capanema","J. P. Salgado Filho"],"url":""},{"key":"l9784:3","law":"l9784","ref":"3","label":"Lei do Processo Administrativo Federal · Art. 3","paragraphs":["Art. 3º O administrado tem os seguintes direitos perante a Administração, sem prejuízo de outros que lhe sejam assegurados:","I - ser tratado com respeito pelas autoridades e servidores, que deverão facilitar o exercício de seus direitos e o cumprimento de suas obrigações;","II - ter ciência da tramitação dos processos administrativos em que tenha a condição de interessado, ter vista dos autos, obter cópias de documentos neles contidos e conhecer as decisões proferidas;","III - formular alegações e apresentar documentos antes da decisão, os quais serão objeto de consideração pelo órgão competente;","IV - fazer-se assistir, facultativamente, por advogado, salvo quando obrigatória a representação, por força de lei."],"url":""},{"key":"l9784:5","law":"l9784","ref":"5","label":"Lei do Processo Administrativo Federal · Art. 5","paragraphs":["Art. 5º O processo administrativo pode iniciar-se de ofício ou a pedido de interessado."],"url":""},{"key":"l9784:8","law":"l9784","ref":"8","label":"Lei do Processo Administrativo Federal · Art. 8","paragraphs":["Art. 8º Quando os pedidos de uma pluralidade de interessados tiverem conteúdo e fundamentos idênticos, poderão ser formulados em um único requerimento, salvo preceito legal em contrário."],"url":""},{"key":"l9784:6","law":"l9784","ref":"6","label":"Lei do Processo Administrativo Federal · Art. 6","paragraphs":["Art. 6º O requerimento inicial do interessado, salvo casos em que for admitida solicitação oral, deve ser formulado por escrito e conter os seguintes dados:","I - órgão ou autoridade administrativa a que se dirige;","II - identificação do interessado ou de quem o represente;","III - domicílio do requerente ou local para recebimento de comunicações;","IV - formulação do pedido, com exposição dos fatos e de seus fundamentos;","V - data e assinatura do requerente ou de seu representante.","Parágrafo único. É vedada à Administração a recusa imotivada de recebimento de documentos, devendo o servidor orientar o interessado quanto ao suprimento de eventuais falhas."],"url":""},{"key":"l9784:7","law":"l9784","ref":"7","label":"Lei do Processo Administrativo Federal · Art. 7","paragraphs":["Art. 7º Os órgãos e entidades administrativas deverão elaborar modelos ou formulários padronizados para assuntos que importem pretensões equivalentes."],"url":""},{"key":"l9784:9","law":"l9784","ref":"9","label":"Lei do Processo Administrativo Federal · Art. 9","paragraphs":["Art. 9º São legitimados como interessados no processo administrativo:","I - pessoas físicas ou jurídicas que o iniciem como titulares de direitos ou interesses individuais ou no exercício do direito de representação;","II - aqueles que, sem terem iniciado o processo, têm direitos ou interesses que possam ser afetados pela decisão a ser adotada;","III - as organizações e associações representativas, no tocante a direitos e interesses coletivos;","IV - as pessoas ou as associações legalmente constituídas quanto a direitos ou interesses difusos."],"url":""},{"key":"l9784:10","law":"l9784","ref":"10","label":"Lei do Processo Administrativo Federal · Art. 10","paragraphs":["Art. 10. São capazes, para fins de processo administrativo, os maiores de dezoito anos, ressalvada previsão especial em ato normativo próprio."],"url":""},{"key":"l9784:13","law":"l9784","ref":"13","label":"Lei do Processo Administrativo Federal · Art. 13","paragraphs":["Art. 13. Não podem ser objeto de delegação:","I - a edição de atos de caráter normativo;","II - a decisão de recursos administrativos;","III - as matérias de competência exclusiva do órgão ou autoridade."],"url":""},{"key":"l9784:12","law":"l9784","ref":"12","label":"Lei do Processo Administrativo Federal · Art. 12","paragraphs":["Art. 12. Um órgão administrativo e seu titular poderão, se não houver impedimento legal, delegar parte da sua competência a outros órgãos ou titulares, ainda que estes não lhe sejam hierarquicamente subordinados, quando for conveniente, em razão de circunstâncias de índole técnica, social, econômica, jurídica ou territorial.","Parágrafo único. O disposto no caput deste artigo aplica-se à delegação de competência dos órgãos colegiados aos respectivos presidentes."],"url":""},{"key":"l9784:18","law":"l9784","ref":"18","label":"Lei do Processo Administrativo Federal · Art. 18","paragraphs":["Art. 18. É impedido de atuar em processo administrativo o servidor ou autoridade que:","I - tenha interesse direto ou indireto na matéria;","II - tenha participado ou venha a participar como perito, testemunha ou representante, ou se tais situações ocorrem quanto ao cônjuge, companheiro ou parente e afins até o terceiro grau;","III - esteja litigando judicial ou administrativamente com o interessado ou respectivo cônjuge ou companheiro."],"url":""},{"key":"l9784:20","law":"l9784","ref":"20","label":"Lei do Processo Administrativo Federal · Art. 20","paragraphs":["Art. 20. Pode ser argüida a suspeição de autoridade ou servidor que tenha amizade íntima ou inimizade notória com algum dos interessados ou com os respectivos cônjuges, companheiros, parentes e afins até o terceiro grau."],"url":""},{"key":"l9784:22","law":"l9784","ref":"22","label":"Lei do Processo Administrativo Federal · Art. 22","paragraphs":["Art. 22. Os atos do processo administrativo não dependem de forma determinada senão quando a lei expressamente a exigir.","§ 1º Os atos do processo devem ser produzidos por escrito, em vernáculo, com a data e o local de sua realização e a assinatura da autoridade responsável.","§ 2º Salvo imposição legal, o reconhecimento de firma somente será exigido quando houver dúvida de autenticidade.","§ 3º A autenticação de documentos exigidos em cópia poderá ser feita pelo órgão administrativo.","§ 4º O processo deverá ter suas páginas numeradas seqüencialmente e rubricadas."],"url":""},{"key":"l9784:26","law":"l9784","ref":"26","label":"Lei do Processo Administrativo Federal · Art. 26","paragraphs":["Art. 26. O órgão competente perante o qual tramita o processo administrativo determinará a intimação do interessado para ciência de decisão ou a efetivação de diligências.","§ 1º A intimação deverá conter:","I - identificação do intimado e nome do órgão ou entidade administrativa;","II - finalidade da intimação;","III - data, hora e local em que deve comparecer;","IV - se o intimado deve comparecer pessoalmente, ou fazer-se representar;","V - informação da continuidade do processo independentemente do seu comparecimento;","VI - indicação dos fatos e fundamentos legais pertinentes.","§ 2º A intimação observará a antecedência mínima de três dias úteis quanto à data de comparecimento.","§ 3º A intimação pode ser efetuada por ciência no processo, por via postal com aviso de recebimento, por telegrama ou outro meio que assegure a certeza da ciência do interessado.","§ 4º No caso de interessados indeterminados, desconhecidos ou com domicílio indefinido, a intimação deve ser efetuada por meio de publicação oficial.","§ 5º As intimações serão nulas quando feitas sem observância das prescrições legais, mas o comparecimento do administrado supre sua falta ou irregularidade."],"url":""},{"key":"l9784:28","law":"l9784","ref":"28","label":"Lei do Processo Administrativo Federal · Art. 28","paragraphs":["Art. 28. Devem ser objeto de intimação os atos do processo que resultem para o interessado em imposição de deveres, ônus, sanções ou restrição ao exercício de direitos e atividades e os atos de outra natureza, de seu interesse."],"url":""},{"key":"l9784:29","law":"l9784","ref":"29","label":"Lei do Processo Administrativo Federal · Art. 29","paragraphs":["Art. 29. As atividades de instrução destinadas a averiguar e comprovar os dados necessários à tomada de decisão realizam-se de ofício ou mediante impulsão do órgão responsável pelo processo, sem prejuízo do direito dos interessados de propor atuações probatórias.","§ 1º O órgão competente para a instrução fará constar dos autos os dados necessários à decisão do processo.","§ 2º Os atos de instrução que exijam a atuação dos interessados devem realizar-se do modo menos oneroso para estes."],"url":""},{"key":"l9784:47","law":"l9784","ref":"47","label":"Lei do Processo Administrativo Federal · Art. 47","paragraphs":["Art. 47. O órgão de instrução que não for competente para emitir a decisão final elaborará relatório indicando o pedido inicial, o conteúdo das fases do procedimento e formulará proposta de decisão, objetivamente justificada, encaminhando o processo à autoridade competente."],"url":""},{"key":"l9784:30","law":"l9784","ref":"30","label":"Lei do Processo Administrativo Federal · Art. 30","paragraphs":["Art. 30. São inadmissíveis no processo administrativo as provas obtidas por meios ilícitos."],"url":""},{"key":"l9784:31","law":"l9784","ref":"31","label":"Lei do Processo Administrativo Federal · Art. 31","paragraphs":["Art. 31. Quando a matéria do processo envolver assunto de interesse geral, o órgão competente poderá, mediante despacho motivado, abrir período de consulta pública para manifestação de terceiros, antes da decisão do pedido, se não houver prejuízo para a parte interessada.","§ 1º A abertura da consulta pública será objeto de divulgação pelos meios oficiais, a fim de que pessoas físicas ou jurídicas possam examinar os autos, fixando-se prazo para oferecimento de alegações escritas.","§ 2º O comparecimento à consulta pública não confere, por si, a condição de interessado do processo, mas confere o direito de obter da Administração resposta fundamentada, que poderá ser comum a todas as alegações substancialmente iguais."],"url":""},{"key":"l9784:32","law":"l9784","ref":"32","label":"Lei do Processo Administrativo Federal · Art. 32","paragraphs":["Art. 32. Antes da tomada de decisão, a juízo da autoridade, diante da relevância da questão, poderá ser realizada audiência pública para debates sobre a matéria do processo."],"url":""},{"key":"l9784:33","law":"l9784","ref":"33","label":"Lei do Processo Administrativo Federal · Art. 33","paragraphs":["Art. 33. Os órgãos e entidades administrativas, em matéria relevante, poderão estabelecer outros meios de participação de administrados, diretamente ou por meio de organizações e associações legalmente reconhecidas."],"url":""},{"key":"l9784:34","law":"l9784","ref":"34","label":"Lei do Processo Administrativo Federal · Art. 34","paragraphs":["Art. 34. Os resultados da consulta e audiência pública e de outros meios de participação de administrados deverão ser apresentados com a indicação do procedimento adotado."],"url":""},{"key":"l9784:35","law":"l9784","ref":"35","label":"Lei do Processo Administrativo Federal · Art. 35","paragraphs":["Art. 35. Quando necessária à instrução do processo, a audiência de outros órgãos ou entidades administrativas poderá ser realizada em reunião conjunta, com a participação de titulares ou representantes dos órgãos competentes, lavrando-se a respectiva ata, a ser juntada aos autos."],"url":""},{"key":"l9784:36","law":"l9784","ref":"36","label":"Lei do Processo Administrativo Federal · Art. 36","paragraphs":["Art. 36. Cabe ao interessado a prova dos fatos que tenha alegado, sem prejuízo do dever atribuído ao órgão competente para a instrução e do disposto no art. 37 desta Lei."],"url":""},{"key":"l9784:37","law":"l9784","ref":"37","label":"Lei do Processo Administrativo Federal · Art. 37","paragraphs":["Art. 37. Quando o interessado declarar que fatos e dados estão registrados em documentos existentes na própria Administração responsável pelo processo ou em outro órgão administrativo, o órgão competente para a instrução proverá, de ofício, à obtenção dos documentos ou das respectivas cópias."],"url":""},{"key":"l9784:38","law":"l9784","ref":"38","label":"Lei do Processo Administrativo Federal · Art. 38","paragraphs":["Art. 38. O interessado poderá, na fase instrutória e antes da tomada da decisão, juntar documentos e pareceres, requerer diligências e perícias, bem como aduzir alegações referentes à matéria objeto do processo.","§ 1º Os elementos probatórios deverão ser considerados na motivação do relatório e da decisão.","§ 2º Somente poderão ser recusadas, mediante decisão fundamentada, as provas propostas pelos interessados quando sejam ilícitas, impertinentes, desnecessárias ou protelatórias."],"url":""},{"key":"l9784:39","law":"l9784","ref":"39","label":"Lei do Processo Administrativo Federal · Art. 39","paragraphs":["Art. 39. Quando for necessária a prestação de informações ou a apresentação de provas pelos interessados ou terceiros, serão expedidas intimações para esse fim, mencionando-se data, prazo, forma e condições de atendimento.","Parágrafo único. Não sendo atendida a intimação, poderá o órgão competente, se entender relevante a matéria, suprir de ofício a omissão, não se eximindo de proferir a decisão."],"url":""},{"key":"l9784:40","law":"l9784","ref":"40","label":"Lei do Processo Administrativo Federal · Art. 40","paragraphs":["Art. 40. Quando dados, atuações ou documentos solicitados ao interessado forem necessários à apreciação de pedido formulado, o não atendimento no prazo fixado pela Administração para a respectiva apresentação implicará arquivamento do processo."],"url":""},{"key":"l9784:41","law":"l9784","ref":"41","label":"Lei do Processo Administrativo Federal · Art. 41","paragraphs":["Art. 41. Os interessados serão intimados de prova ou diligência ordenada, com antecedência mínima de três dias úteis, mencionando-se data, hora e local de realização."],"url":""},{"key":"l9784:42","law":"l9784","ref":"42","label":"Lei do Processo Administrativo Federal · Art. 42","paragraphs":["Art. 42. Quando deva ser obrigatoriamente ouvido um órgão consultivo, o parecer deverá ser emitido no prazo máximo de quinze dias, salvo norma especial ou comprovada necessidade de maior prazo.","§ 1º Se um parecer obrigatório e vinculante deixar de ser emitido no prazo fixado, o processo não terá seguimento até a respectiva apresentação, responsabilizando-se quem der causa ao atraso.","§ 2º Se um parecer obrigatório e não vinculante deixar de ser emitido no prazo fixado, o processo poderá ter prosseguimento e ser decidido com sua dispensa, sem prejuízo da responsabilidade de quem se omitiu no atendimento."],"url":""},{"key":"l9784:43","law":"l9784","ref":"43","label":"Lei do Processo Administrativo Federal · Art. 43","paragraphs":["Art. 43. Quando por disposição de ato normativo devam ser previamente obtidos laudos técnicos de órgãos administrativos e estes não cumprirem o encargo no prazo assinalado, o órgão responsável pela instrução deverá solicitar laudo técnico de outro órgão dotado de qualificação e capacidade técnica equivalentes."],"url":""},{"key":"l9784:44","law":"l9784","ref":"44","label":"Lei do Processo Administrativo Federal · Art. 44","paragraphs":["Art. 44. Encerrada a instrução, o interessado terá o direito de manifestar-se no prazo máximo de dez dias, salvo se outro prazo for legalmente fixado."],"url":""},{"key":"l9784:45","law":"l9784","ref":"45","label":"Lei do Processo Administrativo Federal · Art. 45","paragraphs":["Art. 45. Em caso de risco iminente, a Administração Pública poderá motivadamente adotar providências acauteladoras sem a prévia manifestação do interessado."],"url":""},{"key":"l9784:46","law":"l9784","ref":"46","label":"Lei do Processo Administrativo Federal · Art. 46","paragraphs":["Art. 46. Os interessados têm direito à vista do processo e a obter certidões ou cópias reprográficas dos dados e documentos que o integram, ressalvados os dados e documentos de terceiros protegidos por sigilo ou pelo direito à privacidade, à honra e à imagem."],"url":""},{"key":"l9784:50","law":"l9784","ref":"50","label":"Lei do Processo Administrativo Federal · Art. 50","paragraphs":["Art. 50. Os atos administrativos deverão ser motivados, com indicação dos fatos e dos fundamentos jurídicos, quando:","I - neguem, limitem ou afetem direitos ou interesses;","II - imponham ou agravem deveres, encargos ou sanções;","III - decidam processos administrativos de concurso ou seleção pública;","IV - dispensem ou declarem a inexigibilidade de processo licitatório;","V - decidam recursos administrativos;","VI - decorram de reexame de ofício;","VII - deixem de aplicar jurisprudência firmada sobre a questão ou discrepem de pareceres, laudos, propostas e relatórios oficiais;","VIII - importem anulação, revogação, suspensão ou convalidação de ato administrativo.","§ 1º A motivação deve ser explícita, clara e congruente, podendo consistir em declaração de concordância com fundamentos de anteriores pareceres, informações, decisões ou propostas, que, neste caso, serão parte integrante do ato.","§ 2º Na solução de vários assuntos da mesma natureza, pode ser utilizado meio mecânico que reproduza os fundamentos das decisões, desde que não prejudique direito ou garantia dos interessados.","§ 3º A motivação das decisões de órgãos colegiados e comissões ou de decisões orais constará da respectiva ata ou de termo escrito."],"url":""},{"key":"l9784:49-A","law":"l9784","ref":"49-A","label":"Lei do Processo Administrativo Federal · Art. 49-A","paragraphs":["Art. 49-A. No âmbito da Administração Pública federal, as decisões administrativas que exijam a participação de 3 (três) ou mais setores, órgãos ou entidades poderão ser tomadas mediante decisão coordenada, sempre que:","I - for justificável pela relevância da matéria; e","II - houver discordância que prejudique a celeridade do processo administrativo decisório.","§ 1º Para os fins desta Lei, considera-se decisão coordenada a instância de natureza interinstitucional ou intersetorial que atua de forma compartilhada com a finalidade de simplificar o processo administrativo mediante participação concomitante de todas as autoridades e agentes decisórios e dos responsáveis pela instrução técnico-jurídica, observada a natureza do objeto e a compatibilidade do procedimento e de sua formalização com a legislação pertinente.","§ 2º (VETADO na Lei nº 14.210, de 30/9/2021)","§ 3º (VETADO na Lei nº 14.210, de 30/9/2021)","§ 4º A decisão coordenada não exclui a responsabilidade originária de cada órgão ou autoridade envolvida.","§ 5º A decisão coordenada obedecerá aos princípios da legalidade, da eficiência e da transparência, com utilização, sempre que necessário, da simplificação do procedimento e da concentração das instâncias decisórias.","§ 6º Não se aplica a decisão coordenada aos processos administrativos:","I - de licitação;","II - relacionados ao poder sancionador; ou","III - em que estejam envolvidas autoridades de Poderes distintos. (Artigo acrescido pela Lei nº 14.210, de 30/9/2021)"],"url":""},{"key":"l9784:49-G","law":"l9784","ref":"49-G","label":"Lei do Processo Administrativo Federal · Art. 49-G","paragraphs":["Art. 49-G. A conclusão dos trabalhos da decisão coordenada será consolidada em ata, que conterá as seguintes informações:","I - relato sobre os itens da pauta;","II - síntese dos fundamentos aduzidos;","III - síntese das teses pertinentes ao objeto da convocação;","IV - registro das orientações, das diretrizes, das soluções ou das propostas de atos governamentais relativos ao objeto da convocação;","V - posicionamento dos participantes para subsidiar futura atuação governamental em matéria idêntica ou similar; e","VI - decisão de cada órgão ou entidade relativa à matéria sujeita à sua competência.","§ 1º Até a assinatura da ata, poderá ser complementada a fundamentação da decisão da autoridade ou do agente a respeito de matéria de competência do órgão ou da entidade representada.","§ 2º (VETADO na Lei nº 14.210, de 30/9/2021)","§ 3º A ata será publicada por extrato no Diário Oficial da União, do qual deverão constar, além do registro referido no inciso IV do caput deste artigo, os dados identificadores da decisão coordenada e o órgão e o local em que se encontra a ata em seu inteiro teor, para conhecimento dos interessados. (Artigo acrescido pela Lei nº 14.210, de 30/9/2021)"],"url":""},{"key":"l9784:49-B","law":"l9784","ref":"49-B","label":"Lei do Processo Administrativo Federal · Art. 49-B","paragraphs":["Art. 49-B. Poderão habilitar-se a participar da decisão coordenada, na qualidade de ouvintes, os interessados de que trata o art. 9º desta Lei.","Parágrafo único. A participação na reunião, que poderá incluir direito a voz, será deferida por decisão irrecorrível da autoridade responsável pela convocação da decisão coordenada. (Artigo acrescido pela Lei nº 14.210, de 30/9/2021)"],"url":""},{"key":"l9784:49-C","law":"l9784","ref":"49-C","label":"Lei do Processo Administrativo Federal · Art. 49-C","paragraphs":["Art. 49-C. (VETADO na Lei nº 14.210, de 30/9/2021)"],"url":""},{"key":"l9784:49-D","law":"l9784","ref":"49-D","label":"Lei do Processo Administrativo Federal · Art. 49-D","paragraphs":["Art. 49-D. Os participantes da decisão coordenada deverão ser intimados na forma do art. 26 desta Lei. (Artigo acrescido pela Lei nº 14.210, de 30/9/2021)"],"url":""},{"key":"l9784:49-E","law":"l9784","ref":"49-E","label":"Lei do Processo Administrativo Federal · Art. 49-E","paragraphs":["Art. 49-E. Cada órgão ou entidade participante é responsável pela elaboração de documento específico sobre o tema atinente à respectiva competência, a fim de subsidiar os trabalhos e integrar o processo da decisão coordenada.","Parágrafo único. O documento previsto no caput deste artigo abordará a questão objeto da decisão coordenada e eventuais precedentes. (Artigo acrescido pela Lei nº 14.210, de 30/9/2021)"],"url":""},{"key":"l9784:49-F","law":"l9784","ref":"49-F","label":"Lei do Processo Administrativo Federal · Art. 49-F","paragraphs":["Art. 49-F. Eventual dissenso na solução do objeto da decisão coordenada deverá ser manifestado durante as reuniões, de forma fundamentada, acompanhado das propostas de solução e de alteração necessárias para a resolução da questão.","Parágrafo único. Não poderá ser arguida matéria estranha ao objeto da convocação. (Artigo acrescido pela Lei nº 14.210, de 30/9/2021)"],"url":""},{"key":"l9784:51","law":"l9784","ref":"51","label":"Lei do Processo Administrativo Federal · Art. 51","paragraphs":["Art. 51. O interessado poderá, mediante manifestação escrita, desistir total ou parcialmente do pedido formulado ou, ainda, renunciar a direitos disponíveis.","§ 1º Havendo vários interessados, a desistência ou renúncia atinge somente quem a tenha formulado.","§ 2º A desistência ou renúncia do interessado, conforme o caso, não prejudica o prosseguimento do processo, se a Administração considerar que o interesse público assim o exige."],"url":""},{"key":"l9784:52","law":"l9784","ref":"52","label":"Lei do Processo Administrativo Federal · Art. 52","paragraphs":["Art. 52. O órgão competente poderá declarar extinto o processo quando exaurida sua finalidade ou o objeto da decisão se tornar impossível, inútil ou prejudicado por fato superveniente."],"url":""},{"key":"l9784:53","law":"l9784","ref":"53","label":"Lei do Processo Administrativo Federal · Art. 53","paragraphs":["Art. 53. A Administração deve anular seus próprios atos, quando eivados de vício de legalidade, e pode revogá-los por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos."],"url":""},{"key":"l9784:55","law":"l9784","ref":"55","label":"Lei do Processo Administrativo Federal · Art. 55","paragraphs":["Art. 55. Em decisão na qual se evidencie não acarretarem lesão ao interesse público nem prejuízo a terceiros, os atos que apresentarem defeitos sanáveis poderão ser convalidados pela própria Administração."],"url":""},{"key":"l9784:54","law":"l9784","ref":"54","label":"Lei do Processo Administrativo Federal · Art. 54","paragraphs":["Art. 54. O direito da Administração de anular os atos administrativos de que decorram efeitos favoráveis para os destinatários decai em cinco anos, contados da data em que foram praticados, salvo comprovada má-fé.","§ 1º No caso de efeitos patrimoniais contínuos, o prazo de decadência contar-se-á da percepção do primeiro pagamento.","§ 2º Considera-se exercício do direito de anular qualquer medida de autoridade administrativa que importe impugnação à validade do ato."],"url":""},{"key":"l9784:56","law":"l9784","ref":"56","label":"Lei do Processo Administrativo Federal · Art. 56","paragraphs":["Art. 56. Das decisões administrativas cabe recurso, em face de razões de legalidade e de mérito.","§ 1º O recurso será dirigido à autoridade que proferiu a decisão, a qual, se não a reconsiderar no prazo de cinco dias, o encaminhará à autoridade superior.","§ 2º Salvo exigência legal, a interposição de recurso administrativo independe de caução.","§ 3º Se o recorrente alegar que a decisão administrativa contraria enunciado da súmula vinculante, caberá à autoridade prolatora da decisão impugnada, se não a reconsiderar, explicitar, antes de encaminhar o recurso à autoridade superior, as razões da aplicabilidade ou inaplicabilidade da súmula, conforme o caso. (Parágrafo acrescido pela Lei nº 11.417, de 19/12/2006, publicada no DOU de 20/12/2006, em vigor 3 (três) meses após a publicação)"],"url":""},{"key":"l9784:64","law":"l9784","ref":"64","label":"Lei do Processo Administrativo Federal · Art. 64","paragraphs":["Art. 64. O órgão competente para decidir o recurso poderá confirmar, modificar, anular ou revogar, total ou parcialmente, a decisão recorrida, se a matéria for de sua competência.","Parágrafo único. Se da aplicação do disposto neste artigo puder decorrer gravame à situação do recorrente, este deverá ser cientificado para que formule suas alegações antes da decisão."],"url":""},{"key":"l9784:57","law":"l9784","ref":"57","label":"Lei do Processo Administrativo Federal · Art. 57","paragraphs":["Art. 57. O recurso administrativo tramitará no máximo por três instâncias administrativas, salvo disposição legal diversa."],"url":""},{"key":"l9784:58","law":"l9784","ref":"58","label":"Lei do Processo Administrativo Federal · Art. 58","paragraphs":["Art. 58. Têm legitimidade para interpor recurso administrativo:","I - os titulares de direitos e interesses que forem parte no processo;","II - aqueles cujos direitos ou interesses forem indiretamente afetados pela decisão recorrida;","III - as organizações e associações representativas, no tocante a direitos e interesses coletivos;","IV - os cidadãos ou associações, quanto a direitos ou interesses difusos."],"url":""},{"key":"l9784:59","law":"l9784","ref":"59","label":"Lei do Processo Administrativo Federal · Art. 59","paragraphs":["Art. 59. Salvo disposição legal específica, é de dez dias o prazo para interposição de recurso administrativo, contado a partir da ciência ou divulgação oficial da decisão recorrida.","§ 1º Quando a lei não fixar prazo diferente, o recurso administrativo deverá ser decidido no prazo máximo de trinta dias, a partir do recebimento dos autos pelo órgão competente.","§ 2º O prazo mencionado no parágrafo anterior poderá ser prorrogado por igual período, ante justificativa explícita."],"url":""},{"key":"l9784:60","law":"l9784","ref":"60","label":"Lei do Processo Administrativo Federal · Art. 60","paragraphs":["Art. 60. O recurso interpõe-se por meio de requerimento no qual o recorrente deverá expor os fundamentos do pedido de reexame, podendo juntar os documentos que julgar convenientes."],"url":""},{"key":"l9784:61","law":"l9784","ref":"61","label":"Lei do Processo Administrativo Federal · Art. 61","paragraphs":["Art. 61. Salvo disposição legal em contrário, o recurso não tem efeito suspensivo.","Parágrafo único. Havendo justo receio de prejuízo de difícil ou incerta reparação decorrente da execução, a autoridade recorrida ou a imediatamente superior poderá, de ofício ou a pedido, dar efeito suspensivo ao recurso."],"url":""},{"key":"l9784:62","law":"l9784","ref":"62","label":"Lei do Processo Administrativo Federal · Art. 62","paragraphs":["Art. 62. Interposto o recurso, o órgão competente para dele conhecer deverá intimar os demais interessados para que, no prazo de cinco dias úteis, apresentem alegações."],"url":""},{"key":"l9784:63","law":"l9784","ref":"63","label":"Lei do Processo Administrativo Federal · Art. 63","paragraphs":["Art. 63. O recurso não será conhecido quando interposto:","I - fora do prazo;","II - perante órgão incompetente;","III - por quem não seja legitimado;","IV - após exaurida a esfera administrativa.","§ 1º Na hipótese do inciso II, será indicada ao recorrente a autoridade competente, sendo-lhe devolvido o prazo para recurso.","§ 2º O não conhecimento do recurso não impede a Administração de rever de ofício o ato ilegal, desde que não ocorrida preclusão administrativa."],"url":""},{"key":"l9784:65","law":"l9784","ref":"65","label":"Lei do Processo Administrativo Federal · Art. 65","paragraphs":["Art. 65. Os processos administrativos de que resultem sanções poderão ser revistos, a qualquer tempo, a pedido ou de ofício, quando surgirem fatos novos ou circunstâncias relevantes suscetíveis de justificar a inadequação da sanção aplicada.","Parágrafo único. Da revisão do processo não poderá resultar agravamento da sanção."],"url":""},{"key":"l9784:66","law":"l9784","ref":"66","label":"Lei do Processo Administrativo Federal · Art. 66","paragraphs":["Art. 66. Os prazos começam a correr a partir da data da cientificação oficial, excluindo-se da contagem o dia do começo e incluindo-se o do vencimento.","§ 1º Considera-se prorrogado o prazo até o primeiro dia útil seguinte se o vencimento cair em dia em que não houver expediente ou este for encerrado antes da hora normal.","§ 2º Os prazos expressos em dias contam-se de modo contínuo.","§ 3º Os prazos fixados em meses ou anos contam-se de data a data. Se no mês do vencimento não houver o dia equivalente àquele do início do prazo, tem-se como termo o último dia do mês."],"url":""},{"key":"l9784:67","law":"l9784","ref":"67","label":"Lei do Processo Administrativo Federal · Art. 67","paragraphs":["Art. 67. Salvo motivo de força maior devidamente comprovado, os prazos processuais não se suspendem."],"url":""},{"key":"l9784:24","law":"l9784","ref":"24","label":"Lei do Processo Administrativo Federal · Art. 24","paragraphs":["Art. 24. Inexistindo disposição específica, os atos do órgão ou autoridade responsável pelo processo e dos administrados que dele participem devem ser praticados no prazo de cinco dias, salvo motivo de força maior.","Parágrafo único. O prazo previsto neste artigo pode ser dilatado até o dobro, mediante comprovada justificação."],"url":""},{"key":"l9784:49","law":"l9784","ref":"49","label":"Lei do Processo Administrativo Federal · Art. 49","paragraphs":["Art. 49. Concluída a instrução de processo administrativo, a Administração tem o prazo de até trinta dias para decidir, salvo prorrogação por igual período expressamente motivada."],"url":""},{"key":"l9784:4","law":"l9784","ref":"4","label":"Lei do Processo Administrativo Federal · Art. 4","paragraphs":["Art. 4º São deveres do administrado perante a Administração, sem prejuízo de outros previstos em ato normativo:","I - expor os fatos conforme a verdade;","II - proceder com lealdade, urbanidade e boa-fé;","III - não agir de modo temerário;","IV - prestar as informações que lhe forem solicitadas e colaborar para o esclarecimento dos fatos."],"url":""},{"key":"l9784:11","law":"l9784","ref":"11","label":"Lei do Processo Administrativo Federal · Art. 11","paragraphs":["Art. 11. A competência é irrenunciável e se exerce pelos órgãos administrativos a que foi atribuída como própria, salvo os casos de delegação e avocação legalmente admitidos."],"url":""},{"key":"l9784:14","law":"l9784","ref":"14","label":"Lei do Processo Administrativo Federal · Art. 14","paragraphs":["Art. 14. O ato de delegação e sua revogação deverão ser publicados no meio oficial.","§ 1º O ato de delegação especificará as matérias e poderes transferidos, os limites da atuação do delegado, a duração e os objetivos da delegação e o recurso cabível, podendo conter ressalva de exercício da atribuição delegada.","§ 2º O ato de delegação é revogável a qualquer tempo pela autoridade delegante.","§ 3º As decisões adotadas por delegação devem mencionar explicitamente esta qualidade e considerar-se-ão editadas pelo delegado."],"url":""},{"key":"l9784:15","law":"l9784","ref":"15","label":"Lei do Processo Administrativo Federal · Art. 15","paragraphs":["Art. 15. Será permitida, em caráter excepcional e por motivos relevantes devidamente justificados, a avocação temporária de competência atribuída a órgão hierarquicamente inferior."],"url":""},{"key":"l9784:16","law":"l9784","ref":"16","label":"Lei do Processo Administrativo Federal · Art. 16","paragraphs":["Art. 16. Os órgãos e entidades administrativas divulgarão publicamente os locais das respectivas sedes e, quando conveniente, a unidade fundacional competente em matéria de interesse especial."],"url":""},{"key":"l9784:17","law":"l9784","ref":"17","label":"Lei do Processo Administrativo Federal · Art. 17","paragraphs":["Art. 17. Inexistindo competência legal específica, o processo administrativo deverá ser iniciado perante a autoridade de menor grau hierárquico para decidir."],"url":""},{"key":"l9784:19","law":"l9784","ref":"19","label":"Lei do Processo Administrativo Federal · Art. 19","paragraphs":["Art. 19. A autoridade ou servidor que incorrer em impedimento deve comunicar o fato à autoridade competente, abstendo-se de atuar.","Parágrafo único. A omissão do dever de comunicar o impedimento constitui falta grave, para efeitos disciplinares."],"url":""},{"key":"l9784:21","law":"l9784","ref":"21","label":"Lei do Processo Administrativo Federal · Art. 21","paragraphs":["Art. 21. O indeferimento de alegação de suspeição poderá ser objeto de recurso, sem efeito suspensivo."],"url":""},{"key":"l9784:23","law":"l9784","ref":"23","label":"Lei do Processo Administrativo Federal · Art. 23","paragraphs":["Art. 23. Os atos do processo devem realizar-se em dias úteis, no horário normal de funcionamento da repartição na qual tramitar o processo.","Parágrafo único. Serão concluídos depois do horário normal os atos já iniciados, cujo adiamento prejudique o curso regular do procedimento ou cause dano ao interessado ou à Administração."],"url":""},{"key":"l9784:25","law":"l9784","ref":"25","label":"Lei do Processo Administrativo Federal · Art. 25","paragraphs":["Art. 25. Os atos do processo devem realizar-se preferencialmente na sede do órgão, cientificando-se o interessado se outro for o local de realização."],"url":""},{"key":"l9784:27","law":"l9784","ref":"27","label":"Lei do Processo Administrativo Federal · Art. 27","paragraphs":["Art. 27. O desatendimento da intimação não importa o reconhecimento da verdade dos fatos, nem a renúncia a direito pelo administrado.","Parágrafo único. No prosseguimento do processo, será garantido direito de ampla defesa ao interessado."],"url":""},{"key":"l9784:48","law":"l9784","ref":"48","label":"Lei do Processo Administrativo Federal · Art. 48","paragraphs":["Art. 48. A Administração tem o dever de explicitamente emitir decisão nos processos administrativos e sobre solicitações ou reclamações, em matéria de sua competência."],"url":""},{"key":"l9784:64-A","law":"l9784","ref":"64-A","label":"Lei do Processo Administrativo Federal · Art. 64-A","paragraphs":["Art. 64-A. Se o recorrente alegar violação de enunciado da súmula vinculante, o órgão competente para decidir o recurso explicitará as razões da aplicabilidade ou inaplicabilidade da súmula, conforme o caso. (Artigo acrescido pela Lei nº 11.417, de 19/12/2006, publicada no DOU de 20/12/2006, em vigor 3 (três) meses após a publicação)"],"url":""},{"key":"l9784:64-B","law":"l9784","ref":"64-B","label":"Lei do Processo Administrativo Federal · Art. 64-B","paragraphs":["Art. 64-B. Acolhida pelo Supremo Tribunal Federal a reclamação fundada em violação de enunciado da súmula vinculante, dar-se-á ciência à autoridade prolatora e ao órgão competente para o julgamento do recurso, que deverão adequar as futuras decisões administrativas em casos semelhantes, sob pena de responsabilização pessoal nas esferas cível, administrativa e penal. (Artigo acrescido pela Lei nº 11.417, de 19/12/2006, publicada no DOU de 20/12/2006, em vigor 3 (três) meses após a publicação)"],"url":""},{"key":"cf:5","law":"cf","ref":"5","label":"Constituição Federal · CF/88 · Art. 5","paragraphs":["Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes:","I - homens e mulheres são iguais em direitos e obrigações, nos termos desta Constituição;","II - ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei;","III - ninguém será submetido a tortura nem a tratamento desumano ou degradante;","IV - é livre a manifestação do pensamento, sendo vedado o anonimato;","V - é assegurado o direito de resposta, proporcional ao agravo, além da indenização por dano material, moral ou à imagem;","VI - é inviolável a liberdade de consciência e de crença, sendo assegurado o livre exercício dos cultos religiosos e garantida, na forma da lei, a proteção aos locais de culto e a suas liturgias;","VII - é assegurada, nos termos da lei, a prestação de assistência religiosa nas entidades civis e militares de internação coletiva;","VIII - ninguém será privado de direitos por motivo de crença religiosa ou de convicção filosófica ou política, salvo se as invocar para eximir-se de obrigação legal a todos imposta e recusar-se a cumprir prestação alternativa, fixada em lei;","IX - é livre a expressão da atividade intelectual, artística, científica e de comunicação, independentemente de censura ou licença;","X - são invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação;","XI - a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial;","XII - é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal;","XIII - é livre o exercício de qualquer trabalho, ofício ou profissão, atendidas as qualificações profissionais que a lei estabelecer;","XIV - é assegurado a todos o acesso à informação e resguardado o sigilo da fonte, quando necessário ao exercício profissional;","XV - é livre a locomoção no território nacional em tempo de paz, podendo qualquer pessoa, nos termos da lei, nele entrar, permanecer ou dele sair com seus bens;","XVI - todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso à autoridade competente;","XVII - é plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar;","XVIII - a criação de associações e, na forma da lei, a de cooperativas independem de autorização, sendo vedada a interferência estatal em seu funcionamento;","XIX - as associações só poderão ser compulsoriamente dissolvidas ou ter suas atividades suspensas por decisão judicial, exigindo-se, no primeiro caso, o trânsito em julgado;","XX - ninguém poderá ser compelido a associar-se ou a permanecer associado;","XXI - as entidades associativas, quando expressamente autorizadas, têm legitimidade para representar seus filiados judicial ou extrajudicialmente;","XXII - é garantido o direito de propriedade;","XXIII - a propriedade atenderá a sua função social;","XXIV - a lei estabelecerá o procedimento para desapropriação por necessidade ou utilidade pública, ou por interesse social, mediante justa e prévia indenização em dinheiro, ressalvados os casos previstos nesta Constituição;","XXV - no caso de iminente perigo público, a autoridade competente poderá usar de propriedade particular, assegurada ao proprietário indenização ulterior, se houver dano;","XXVI - a pequena propriedade rural, assim definida em lei, desde que trabalhada pela família, não será objeto de penhora para pagamento de débitos decorrentes de sua atividade produtiva, dispondo a lei sobre os meios de financiar o seu desenvolvimento;","XXVII - aos autores pertence o direito exclusivo de utilização, publicação ou reprodução de suas obras, transmissível aos herdeiros pelo tempo que a lei fixar;","XXVIII - são assegurados, nos termos da lei:","a) a proteção às participações individuais em obras coletivas e à reprodução da imagem e voz humanas, inclusive nas atividades desportivas;","b) o direito de fiscalização do aproveitamento econômico das obras que criarem ou de que participarem aos criadores, aos intérpretes e às respectivas representações sindicais e associativas;","XXIX - a lei assegurará aos autores de inventos industriais privilégio temporário para sua utilização, bem como proteção às criações industriais, à propriedade das marcas, aos nomes de empresas e a outros signos distintivos, tendo em vista o interesse social e o desenvolvimento tecnológico e econômico do País;","XXX - é garantido o direito de herança;","XXXI - a sucessão de bens de estrangeiros situados no País será regulada pela lei brasileira em benefício do cônjuge ou dos filhos brasileiros, sempre que não lhes seja mais favorável a lei pessoal do de cujus;","XXXII - o Estado promoverá, na forma da lei, a defesa do consumidor;","XXXIII - todos têm direito a receber dos órgãos públicos informações de seu interesse particular, ou de interesse coletivo ou geral, que serão prestadas no prazo da lei, sob pena de responsabilidade, ressalvadas aquelas cujo sigilo seja imprescindível à segurança da sociedade e do Estado;","XXXIV - são a todos assegurados, independentemente do pagamento de taxas:","a) o direito de petição aos poderes públicos em defesa de direitos ou contra ilegalidade ou abuso de poder;","b) a obtenção de certidões em repartições públicas, para defesa de direitos e esclarecimento de situações de interesse pessoal;","XXXV - a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito;","XXXVI - a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a coisa julgada;","XXXVII - não haverá juízo ou tribunal de exceção;","XXXVIII - é reconhecida a instituição do júri, com a organização que lhe der a lei, assegurados:","a) a plenitude de defesa;","b) o sigilo das votações;","c) a soberania dos veredictos;","d) a competência para o julgamento dos crimes dolosos contra a vida;","XXXIX - não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal;","XL - a lei penal não retroagirá, salvo para beneficiar o réu;","XLI - a lei punirá qualquer discriminação atentatória dos direitos e liberdades fundamentais;","XLII - a prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão, nos termos da lei;","XLIII - a lei considerará crimes inafiançáveis e insuscetíveis de graça ou anistia a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins, o terrorismo e os definidos como crimes hediondos, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem;","XLIV - constitui crime inafiançável e imprescritível a ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado democrático;","XLV - nenhuma pena passará da pessoa do condenado, podendo a obrigação de reparar o dano e a decretação do perdimento de bens ser, nos termos da lei, estendidas aos sucessores e contra eles executadas, até o limite do valor do patrimônio transferido;","XLVI - a lei regulará a individualização da pena e adotará, entre outras, as seguintes:","a) privação ou restrição da liberdade;","b) perda de bens;","c) multa;","d) prestação social alternativa;","e) suspensão ou interdição de direitos;","XLVII - não haverá penas:","a) de morte, salvo em caso de guerra declarada, nos termos do art. 84, XIX;","b) de caráter perpétuo;","c) de trabalhos forçados;","d) de banimento;","e) cruéis;","XLVIII - a pena será cumprida em estabelecimentos distintos, de acordo com a natureza do delito, a idade e o sexo do apenado;","XLIX - é assegurado aos presos o respeito à integridade física e moral;","L - às presidiárias serão asseguradas condições para que possam permanecer com seus filhos durante o período de amamentação;","LI - nenhum brasileiro será extraditado, salvo o naturalizado, em caso de crime comum, praticado antes da naturalização, ou de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei;","LII - não será concedida extradição de estrangeiro por crime político ou de opinião;","LIII - ninguém será processado nem sentenciado senão pela autoridade competente;","LIV - ninguém será privado da liberdade ou de seus bens sem o devido processo legal;","LV - aos litigantes, em processo judicial ou administrativo, e aos acusados em geral são assegurados o contraditório e a ampla defesa, com os meios e recursos a ela inerentes;","LVI - são inadmissíveis, no processo, as provas obtidas por meios ilícitos;","LVII - ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória;","LVIII - o civilmente identificado não será submetido a identificação criminal, salvo nas hipóteses previstas em lei;","LIX - será admitida ação privada nos crimes de ação pública, se esta não for intentada no prazo legal;","LX - a lei só poderá restringir a publicidade dos atos processuais quando a defesa da intimidade ou o interesse social o exigirem;","LXI - ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;","LXII - a prisão de qualquer pessoa e o local onde se encontre serão comunicados imediatamente ao juiz competente e à família do preso ou à pessoa por ele indicada;","LXIII - o preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência da família e de advogado;","LXIV - o preso tem direito à identificação dos responsáveis por sua prisão ou por seu interrogatório policial;","LXV - a prisão ilegal será imediatamente relaxada pela autoridade judiciária;","LXVI - ninguém será levado à prisão ou nela mantido quando a lei admitir a liberdade provisória, com ou sem fiança;","LXVII - não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento voluntário e inescusável de obrigação alimentícia e a do depositário infiel;","LXVIII - conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder;","LXIX - conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for autoridade pública ou agente de pessoa jurídica no exercício de atribuições do poder público;","LXX - o mandado de segurança coletivo pode ser impetrado por:","a) partido político com representação no Congresso Nacional;","b) organização sindical, entidade de classe ou associação legalmente constituída e em funcionamento há pelo menos um ano, em defesa dos interesses de seus membros ou associados;","LXXI - conceder-se-á mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais e das prerrogativas inerentes à nacionalidade, à soberania e à cidadania;","LXXII - conceder-se-á habeas data:","a) para assegurar o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público;","b) para a retificação de dados, quando não se prefira fazê-lo por processo sigiloso, judicial ou administrativo;","LXXIII - qualquer cidadão é parte legítima para propor ação popular que vise a anular ato lesivo ao patrimônio público ou de entidade de que o Estado participe, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural, ficando o autor, salvo comprovada má-fé, isento de custas judiciais e do ônus da sucumbência;","LXXIV - o Estado prestará assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos;","LXXV - o Estado indenizará o condenado por erro judiciário, assim como o que ficar preso além do tempo fixado na sentença;","LXXVI - são gratuitos para os reconhecidamente pobres, na forma da lei:","a) o registro civil de nascimento;","b) a certidão de óbito;","LXXVII - são gratuitas as ações de habeas corpus e habeas data, e, na forma da lei, os atos necessários ao exercício da cidadania.","LXXVIII - a todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação. (Inciso acrescido pela Emenda Constitucional nº 45, de 2004)","LXXIX - é assegurado, nos termos da lei, o direito à proteção dos dados pessoais, inclusive nos meios digitais. (Inciso acrescido pela Emenda Constitucional nº 115, de 2022)","§ 1º As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata.","§ 2º Os direitos e garantias expressos nesta Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados, ou dos tratados internacionais em que a República Federativa do Brasil seja parte.","§ 3º Os tratados e convenções internacionais sobre direitos humanos que forem aprovados, em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, serão equivalentes às emendas constitucionais. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)","§ 4º O Brasil se submete à jurisdição de Tribunal Penal Internacional a cuja criação tenha manifestado adesão. (Parágrafo acrescido pela Emenda Constitucional nº 45, de 2004)"],"url":""},{"key":"l9784:68","law":"l9784","ref":"68","label":"Lei do Processo Administrativo Federal · Art. 68","paragraphs":["Art. 68. As sanções, a serem aplicadas por autoridade competente, terão natureza pecuniária ou consistirão em obrigação de fazer ou de não fazer, assegurado sempre o direito de defesa."],"url":""},{"key":"l9784:69","law":"l9784","ref":"69","label":"Lei do Processo Administrativo Federal · Art. 69","paragraphs":["Art. 69. Os processos administrativos específicos continuarão a reger-se por lei própria, aplicando-se-lhes apenas subsidiariamente os preceitos desta Lei."],"url":""},{"key":"l9784:69-A","law":"l9784","ref":"69-A","label":"Lei do Processo Administrativo Federal · Art. 69-A","paragraphs":["Art. 69-A. Terão prioridade na tramitação, em qualquer órgão ou instância, os procedimentos administrativos em que figure como parte ou interessado:","I - pessoa com idade igual ou superior a 60 (sessenta) anos;","II - pessoa portadora de deficiência, física ou mental;","III - (VETADO)","IV - pessoa portadora de tuberculose ativa, esclerose múltipla, neoplasia maligna, hanseníase, paralisia irreversível e incapacitante, cardiopatia grave, doença de Parkinson, espondiloartrose anquilosante, nefropatia grave, hepatopatia grave, estados avançados da doença de Paget (osteíte deformante), contaminação por radiação, síndrome de imunodeficiência adquirida, ou outra doença grave, com base em conclusão da medicina especializada, mesmo que a doença tenha sido contraída após o início do processo.","§ 1º A pessoa interessada na obtenção do benefício, juntando prova de sua condição, deverá requerê-lo à autoridade administrativa competente, que determinará as providências a serem cumpridas.","§ 2º Deferida a prioridade, os autos receberão identificação própria que evidencie o regime de tramitação prioritária.","§ 3º (VETADO)","§ 4º (VETADO) (Artigo acrescido pela Lei nº 12.008, de 29/7/2009)"],"url":""}];})(window);
